import{n as e}from"./data-DMLj1ZLf.js";import{n as t,r as n,t as r}from"./levels-DvemuOtu.js";import{k as i,m as a}from"./remoteConfig-BtANx3jE.js";var o={id:`general`,name:`General / Any company`,icon:`🌐`,tagline:`Broad, balanced questions for any technical interview.`,hq:`Everywhere`,difficulty:3,stack:[`General engineering practice`],values:[`Fundamentals`,`Communication`,`Problem solving`],style:`A well-rounded mix of technical, behavioral, and design questions.`,sample:[]},s=[{id:`google`,name:`Google`,icon:`🔍`,tagline:`Search, Android, Cloud, AI`,hq:`Mountain View, CA`,difficulty:4,stack:[`Go`,`Java`,`Python`,`C++`,`Kubernetes`,`Spanner`,`Bigtable`,`TensorFlow`],values:[`Focus on the user`,`Think 10x`,`Data-driven decisions`,`Move fast without breaking things`],style:`Structured rounds: coding, system design, product sense, and 'Googleyness'. Expect follow-ups that dig one level deeper every time.`,sample:[{q:`How would you design a system that serves trending searches with sub-second latency?`,a:`Two problems: compute trends and serve them fast. Trend computation consumes a stream of search events, aggregates counts in sliding time windows (count-min sketch for memory efficiency), and ranks the deltas. Serving is a read-heavy cache: trending lists are small, recomputed every few minutes, cached at the edge (CDN) and in-memory, so requests never hit the database. Personalization can layer on top with user context. The tradeoffs are freshness vs cost and the risk of echo chambers from regional popularity.`,kp:[`streaming event aggregation`,`sliding time windows`,`count-min sketch`,`cache trending lists at edge`,`freshness vs cost tradeoff`,`personalization layer`]},{q:`Design a rate limiter for Google's public APIs.`,a:`Scale and distribution are the defining constraints: enforce limits across many front-end servers with a shared, fast store (like Redis or a distributed counter), using a token bucket or sliding window per API key. Decisions: limits per key, per user, per endpoint, with burst allowances. Return 429 with Retry-After, and make the limiter itself horizontally scalable and never the bottleneck — degrade gracefully if the counter store is down. Log quota usage for abuse detection and quota analytics.`,kp:[`distributed shared counter store`,`token bucket sliding window`,`per key per endpoint limits`,`429 with retry-after`,`graceful degradation`,`abuse detection telemetry`]},{q:`Walk me through how you'd improve the quality of a search engine's results.`,a:`Define quality metrics first: relevance (NDCG on judged queries), user signals (click-through, dwell time, abandonment), and freshness. Build an evaluation set of hand-judged queries and a feedback loop from user behavior. Then improve in layers: query understanding (spelling, synonyms, intent classification), ranking features (relevance, authority, freshness, personalization), and serving (result diversity, snippets). Every change ships behind an experiment with guardrails, because search is a system where offline gains don't always translate online.`,kp:[`judged evaluation set`,`relevance metrics NDCG`,`user behavior signals`,`query understanding layers`,`experimentation with guardrails`,`offline vs online validation`]},{q:`Tell me about a time you had to choose between shipping fast and shipping right.`,a:`The strong answer follows STAR: a specific situation, what you actually did, the measured outcome. Google interviewers want to hear you reason about tradeoffs explicitly — how you defined 'right' (correctness, security, scalability), what the cost of delay was, and how you de-risked the fast path (feature flags, canary, follow-up fix). They also probe your judgment: when the tradeoff is genuinely false, say so. End with the lesson and how it changed your future decisions.`,kp:[`specific STAR example`,`explicit tradeoff reasoning`,`defined right and cost of delay`,`de-risked fast path`,`measured outcome`,`lesson applied forward`]}]},{id:`meta`,name:`Meta`,icon:`📘`,tagline:`Social platforms, AI, VR`,hq:`Menlo Park, CA`,difficulty:4,stack:[`React`,`Hack/PHP`,`Python`,`C++`,`GraphQL`,`Cassandra`,`TAO`,`PyTorch`],values:[`Move fast`,`Focus on long-term impact`,`Be direct`,`Be bold`],style:`Coding rounds on a shared editor with follow-ups, plus behavioral rounds asking for specific past examples. Direct, fast-paced, outcome-focused.`,sample:[{q:`Design a News Feed that serves a billion users.`,a:`The core is fan-out: on write (push stories to followers' caches at write time) vs on read (pull/merge at request time) — most large systems use a hybrid: fan-out on write for regular users, on read for celebrities with millions of followers. Ranking combines recency, affinity, and content signals, computed in a scoring service. The feed is cached per-user with pagination cursors; heavy read traffic is absorbed by cache tiers. Consistency: eventual is fine — a story appearing slightly late beats the cost of synchronous fan-out.`,kp:[`fan-out on write vs read`,`hybrid for high-follower users`,`ranking signals recency affinity`,`per-user cached feed`,`pagination cursors`,`eventual consistency tradeoff`]},{q:`How would you build a real-time presence and typing indicator for a chat app?`,a:`Presence: each client maintains a WebSocket; the server tracks per-user connection state and publishes presence changes to subscribed friends, with heartbeat timeouts for staleness. Typing indicators: throttled events (typing, stopped) broadcast to the conversation's participants, not stored — they're ephemeral. Scale concerns: a presence service holding connection state must be sharded by user, and fan-out to large groups needs efficient pub/sub. Handle disconnects gracefully — 'online' is a lie the moment a client is silent, so define staleness honestly.`,kp:[`websocket connection state`,`heartbeat and staleness`,`throttled typing events`,`pub sub fan-out`,`shard presence by user`,`ephemeral not stored`]},{q:`How do you reduce the latency of a mobile app's cold start?`,a:`Measure the phases first: process start, framework init, first frame, first content. Attacks: defer non-critical initialization (analytics, SDKs) off the critical path, lazy-load modules, keep the first screen's data local or prefetched, minimize the binary size and JIT work, and render a meaningful placeholder instantly. On Android: avoid heavy work in Application.onCreate. On iOS: watch view controller init and first layout. Track cold start as a metric with a budget, and use profiles, not guesses, to find the real cost.`,kp:[`measure cold start phases`,`defer non-critical init`,`lazy load modules`,`prefetch first screen data`,`minimize binary and jit work`,`cold start as budgeted metric`]},{q:`Tell me about a time you moved fast and broke something. What did you do?`,a:`Meta explicitly wants speed with ownership — the interview is about how you handled the aftermath, not the mistake itself. A strong answer: a specific incident, how you detected it, how you contained it (rollback, feature flag), how you communicated, and the systemic fix that made it unrepeatable. Emphasize owning the outcome end-to-end rather than blaming process, and what you changed in your own workflow. Avoid choosing an example that shows reckless disregard for users.`,kp:[`specific real incident`,`fast detection and containment`,`ownership not blame`,`systemic fix`,`communication`,`changed behavior going forward`]}]},{id:`amazon`,name:`Amazon`,icon:`📦`,tagline:`E-commerce, AWS, logistics`,hq:`Seattle, WA`,difficulty:4,stack:[`Java`,`AWS`,`DynamoDB`,`Lambda`,`S3`,`Kafka`],values:[`Customer obsession`,`Ownership`,`Bias for action`,`Frugality`,`Deliver results`,`Have backbone`],style:`Leadership Principles behavioral rounds with 'tell me about a time' questions, plus system design and coding. Expect 'why Amazon?' and deep dives into your past projects.`,sample:[{q:`Tell me about a time you had to make a decision with incomplete information.`,a:`This is a Leadership Principles question (Bias for action + Are right a lot). Structure: the decision and why it couldn't wait, what you did to gather information fast (experiments, talking to customers, prototypes), the decision itself with your reasoning, and the outcome — including how you monitored and corrected course. Amazon wants evidence you can move with 70% of the information and adjust, not analysis paralysis. Quantify the outcome where you can.`,kp:[`decision with time pressure`,`gathered information fast`,`explicit reasoning`,`acted with partial data`,`monitored and corrected`,`measured outcome`]},{q:`Design a system that tells customers when their package will arrive.`,a:`Split it: order → fulfillment center → carrier → doorstep. The ETA model consumes events from each stage (scan, sort, pickup, delivery attempt) and predicts remaining time using historical carrier performance, distance, and anomalies (weather, holidays). Serving: the promise shown to customers must be conservative — under-promising beats missing. Architecture: event stream for tracking, a prediction service, a cache for the customer-facing promise, and a feedback loop comparing predicted vs actual to improve the model. Handle the failure mode: when tracking data is missing, degrade to a windowed estimate, not a confident lie.`,kp:[`event stream of shipment stages`,`prediction model historical performance`,`conservative promises`,`feedback loop predicted vs actual`,`graceful degradation on missing data`,`customer-facing cache`]},{q:`How would you design a shopping cart service that never loses a customer's items?`,a:`Durability and availability over everything: cart state is written synchronously to a replicated store (DynamoDB-style) before the user gets confirmation; reads can hit cache. Concurrency: versioned updates so two tabs don't silently overwrite each other — last-write-wins only for low-stakes fields, merge or prompt for conflicts. Cart must survive login/logout, device switches, and abandoned sessions (persist with TTL and restore on return). Idempotency for add/remove operations so retries are safe, and instrumentation to catch the silent data loss that availability-focused designs hide.`,kp:[`durable replicated writes`,`versioned conflict handling`,`survives login and devices`,`abandoned cart restore`,`idempotent mutations`,`instrumentation for data loss`]},{q:`Tell me about a time you disagreed with a decision made by your team or manager.`,a:`Amazon's 'Have backbone; disagree and commit' wants: you had a real disagreement, you voiced it constructively with data, you escalated appropriately if needed, and then — if the decision went the other way — you committed fully and executed. The test is whether you can both push back and execute. Show respect for the decision-maker, evidence for your position, and no lingering resentment in your delivery. End with the outcome, whether your view won or not.`,kp:[`real disagreement with evidence`,`voiced constructively`,`appropriate escalation`,`disagree and commit`,`executed fully`,`reflection on outcome`]}]},{id:`microsoft`,name:`Microsoft`,icon:`🪟`,tagline:`Windows, Azure, Office, AI`,hq:`Redmond, WA`,difficulty:3,stack:[`C#`,`TypeScript`,`.NET`,`Azure`,`SQL Server`,`VS Code`,`OpenAI partnership`],values:[`Growth mindset`,`Customer obsession`,`Diverse and inclusive`,`One Microsoft`],style:`Structured rounds with coding, system design, and STAR behavioral questions. Values collaboration and learning; 'tell me about a time you learned something hard' is a classic.`,sample:[{q:`How would you design a cloud storage service like OneDrive (file sync)?`,a:`Core pieces: object storage for file content, a metadata service for the file tree and versions, and a sync client that uploads/downloads with delta sync and conflict resolution. The sync protocol is the heart: change detection, chunked uploads with resume, server-side change log so clients catch up efficiently, and conflict policies (both versions kept, renamed). Add sharing with permissions, offline access with a local cache, and encryption at rest and in transit. Failure handling: partial uploads, interrupted syncs, and reconciliation when client and server disagree.`,kp:[`object storage plus metadata service`,`delta sync and chunked resume`,`change log for catch-up`,`conflict resolution policy`,`offline local cache`,`reconciliation on disagreement`]},{q:`Explain the CAP theorem and how Azure Cosmos DB handles it.`,a:`CAP: under a network partition you choose consistency or availability. Cosmos DB's value is making the choice tunable per request — consistency levels from strong to eventual (bounded staleness, session, consistent prefix, eventual) with corresponding latency and availability tradeoffs, all on a multi-region, multi-master replicated store. You can have a strong-consistency path for money operations and eventual for the feed, in one service. The interview point: know that 'tunable consistency' means you must understand your application's real consistency needs and pick deliberately.`,kp:[`partition forces consistency vs availability`,`tunable consistency levels`,`bounded staleness session consistent prefix`,`multi-region multi-master`,`strong for money eventual for feed`,`deliberate consistency choices`]},{q:`Tell me about a time you learned a new technology quickly to get the job done.`,a:`Microsoft's growth mindset is the theme. Pick a real example with stakes: the technology, why it mattered, your learning method (structured course, building something real, pairing with an expert), how you applied it, and the outcome. They want to see how you learn, not that you knew it already: show deliberate practice, comfort being a beginner, and turning learning into shipped results. A good answer includes what you'd do differently next time.`,kp:[`real stakes and why it mattered`,`deliberate learning method`,`applied to real work`,`measured outcome`,`comfort being a beginner`,`reflection on learning process`]},{q:`Design an AI assistant integration for a productivity product.`,a:`Architecture: a gateway that takes user prompts with product context, calls the LLM with retrieval augmentation (index the user's documents/data so answers are grounded), and streams responses. The hard parts: grounding and accuracy (retrieval quality, citations, hallucination guards), cost and latency control (prompt caching, model tiering, rate limits), privacy (data stays in tenant, no training on customer data), and safety (prompt injection defenses when the assistant reads user documents). Add observability: cost per request, quality sampling, and feedback collection.`,kp:[`gateway with product context`,`retrieval augmented generation`,`grounding and citations`,`prompt injection defense`,`cost latency control and caching`,`tenant privacy guarantees`]}]},{id:`apple`,name:`Apple`,icon:`🍎`,tagline:`Hardware, software, services`,hq:`Cupertino, CA`,difficulty:4,stack:[`Swift`,`Objective-C`,`C/C++`,`Metal`,`WebKit`,`Privacy technologies`],values:[`Design excellence`,`Privacy by design`,`Simplicity`,`Craft and attention to detail`],style:`Deep technical rounds, craft-focused. Expect questions about your actual projects with relentless follow-ups, plus design sensibility and privacy awareness.`,sample:[{q:`How do you keep a scrolling list buttery smooth at 60fps?`,a:`The main thread must never do heavy work: offload image decode, avoid layout in scroll callbacks, reuse cells, and keep cell construction cheap. On iOS specifically: prefetch (UICollectionView prefetching), draw once and cache, avoid shadow/opacity animations that force offscreen rendering, and profile with Instruments (Core Animation, Time Profiler) to find the actual cost. Set a frame drop budget and verify with real-device testing, because simulators lie. The craft answer shows you know the profile is where the truth is.`,kp:[`main thread stays free`,`offload image decode`,`cell reuse and cheap construction`,`prefetch and cached drawing`,`profile with instruments`,`verify on real devices`]},{q:`Explain how you'd design a feature with privacy as a first-class requirement.`,a:`Start from Apple's stance: data minimization — collect the least data, process on-device where possible, and never use user data for purposes they didn't consent to. Design: on-device processing (e.g., on-device ML or local analytics) before any server involvement, differential privacy or aggregation for telemetry, end-to-end encryption for user content, and clear, honest consent flows with easy revocation. Engineering: make privacy the default path (no telemetry without explicit opt-in, app transport security on), and design the data model so nothing unnecessary is stored in the first place.`,kp:[`data minimization`,`on-device processing first`,`end-to-end encryption`,`honest consent and revocation`,`privacy as default not opt-out`,`differential privacy telemetry`]},{q:`Design a system that syncs a user's photos across devices.`,a:`The library is the source of truth, synchronized via a change log: each device applies remote changes and uploads its own with conflict resolution (usually both versions kept with metadata merging). Photos need efficient transfer: full-res originals with optimized device-sized versions, incremental uploads with checksums, and background sync that respects battery and data budgets. Deduplication and content hashing avoid double uploads; the server stores versions and manages device preferences. Add: end-to-end encryption, since photo privacy is non-negotiable, and recovery — the library must survive device loss.`,kp:[`library as source of truth`,`change log sync protocol`,`conflict resolution`,`optimized and full-res versions`,`incremental checksummed uploads`,`end-to-end encryption`]},{q:`Describe a project where you obsessed over the details. What did you do?`,a:`Apple's culture wants evidence of craft: pick something where the difference between good and excellent was visible to users — a micro-interaction, a performance edge, a pixel-perfect layout, an error state designed with care. Show your process: how you noticed the weakness, the iterations (with users or critique), the tradeoffs you rejected, and the final result. Quantify where possible (a 30% faster startup, a crash rate to zero) and connect the detail to the product experience.`,kp:[`detail users could see`,`process of iteration`,`tradeoffs considered and rejected`,`measured improvement`,`connected to user experience`,`craft mindset`]}]},{id:`netflix`,name:`Netflix`,icon:`🎬`,tagline:`Streaming, content, culture`,hq:`Los Gatos, CA`,difficulty:4,stack:[`Java`,`Node.js`,`React`,`GraphQL`,`AWS`,`Cassandra`,`Spinnaker`,`Chaos engineering`],values:[`Judgment`,`Impact`,`Curiosity`,`Courage`,`Freedom and responsibility`,`The Keeper Test`],style:`High-performance culture. Interviews probe judgment and impact; expect 'what would you do differently?' and culture-fit rounds about freedom and responsibility.`,sample:[{q:`Design a video streaming service that must never buffer.`,a:`Never buffering is impossible, so design the experience: adaptive bitrate (ABR) — encode multiple qualities per second, and the player switches quality based on measured bandwidth and buffer health, prioritizing playback continuity over resolution. Content is served from a CDN with caches near users; the most popular content is pre-seeded. The control plane (catalog, recommendations) is separate from the data plane (video bytes). Degradation is by design: lower quality gracefully rather than a frozen frame, and track buffer health as a first-class metric.`,kp:[`adaptive bitrate streaming`,`quality ladder encodings`,`player buffer management`,`CDN with edge caching`,`control plane data plane separation`,`buffer health metrics`]},{q:`How would you design a global content delivery network?`,a:`Layers: origin storage, a hierarchy of caches (regional → edge), and DNS-based routing that sends users to the nearest healthy cache. The interesting problems: cache admission and eviction (what gets cached where — popularity drives this), warm vs cold starts (pre-position popular content before traffic arrives), and failure handling (cache misses escalate to origin; origin must survive stampedes — use request coalescing and capacity headroom). Measure: hit ratio by tier, latency by region, and cost per delivered byte. The economics matter as much as the architecture.`,kp:[`cache hierarchy regional to edge`,`dns routing to nearest cache`,`popularity-driven placement`,`request coalescing on misses`,`hit ratio and latency metrics`,`cost per byte economics`]},{q:`Explain chaos engineering and how you'd introduce it to a team.`,a:`Chaos engineering is confidence through controlled failure: form a steady-state hypothesis (the system keeps serving under this failure), design an experiment with a small blast radius, run it in production or staging, observe, and learn. Start boring: kill a node, fail a dependency, add latency to a service. Prerequisites: observability (you can't learn from chaos you can't see), a blameless culture, and rollback plans. Netflix runs automated chaos (Chaos Monkey) because their architecture must survive instance loss as a design requirement, not an accident.`,kp:[`steady-state hypothesis`,`small blast radius first`,`observability prerequisite`,`blameless learning`,`automated chaos at scale`,`survivable by design`]},{q:`Tell me about a time you had a big impact on a product or system.`,a:`Netflix's Impact value wants scale and ownership: pick something with measurable, significant outcomes — a performance win, a cost reduction, a feature that moved a business metric. Quantify aggressively (X% faster, $Y saved, Z% conversion) and be honest about your specific contribution vs the team's. Show judgment: how you chose this problem over others, how you drove it to completion through ambiguity, and what you'd do differently. The Keeper Test subtext: they're evaluating whether you're the kind of engineer they'd fight to keep.`,kp:[`measurable significant outcome`,`your specific contribution`,`judgment in choosing problem`,`drove through ambiguity`,`quantified impact`,`honest reflection`]}]},{id:`stripe`,name:`Stripe`,icon:`💳`,tagline:`Payments infrastructure`,hq:`San Francisco / Dublin`,difficulty:5,stack:[`Ruby`,`Go`,`Scala`,`React`,`TypeScript`,`PostgreSQL`,`Kafka`,`ML`],values:[`Users first`,`Global optimization`,`Sweat the details`,`Build to last`,`Play long-term games`],style:`Among the hardest: deep API design taste, distributed systems, and 'write an API' questions. Expect sharp follow-ups on edge cases and failure modes.`,sample:[{q:`Design an idempotency layer for a payments API.`,a:`The API must be retry-safe: clients send an Idempotency-Key header, the server stores the request hash and response keyed by that key with a TTL, and retries return the original result instead of double-charging. Storage: a dedicated table with the key as primary key and a unique constraint; concurrent first-time requests need atomic insert-or-return (or a lock) so two racing retries can't both execute. Scrub the stored data for compliance (keys expire, responses truncated). Also handle: key reuse across different requests is an error, and key collisions are a correctness bug that costs money.`,kp:[`idempotency key from client`,`store request hash and response`,`atomic insert to prevent races`,`retry returns original result`,`ttl and data scrubbing`,`key reuse is an error`]},{q:`Walk me through what happens when a customer pays with Stripe.`,a:`The payment journey: the client creates a PaymentIntent, Stripe returns a client secret, the customer authorizes (card details via Stripe.js/Element or a redirect for wallets), and Stripe confirms with the network. The money moves through: authorization → capture (or automatic capture) → settlement, with the balance updated via a ledger — double-entry, append-only, reconciled against network reports. Webhooks notify the merchant asynchronously (idempotent, signed). Failure paths: decline (3DS challenges, retry logic), timeouts (reconciliation catches ambiguity), and refunds as separate flows with their own lifecycle.`,kp:[`payment intent lifecycle`,`authorization capture settlement`,`append-only double-entry ledger`,`signed idempotent webhooks`,`decline and 3ds handling`,`reconciliation for ambiguous outcomes`]},{q:`Design a dashboard API that reports revenue metrics in real time.`,a:`The hard part is what 'real time' means for money: reporting must be correct, so the pipeline is: ledger events → stream → aggregation service → serving API, with a reconciliation pass that corrects the real-time numbers against the settled truth. Design for correctness over immediacy: show provisional numbers clearly labeled, and let final numbers replace them. Serving: pre-aggregated rollups (daily, monthly, per merchant) in a fast store with cache; the API paginates and filters server-side. Guard the join: metrics must be consistent across endpoints (same definitions everywhere) or the dashboard loses trust.`,kp:[`ledger events to aggregation pipeline`,`reconciliation against settled truth`,`provisional vs final labeling`,`pre-aggregated rollups`,`consistent metric definitions`,`server-side filtering pagination`]},{q:`Tell me about a time you sweat the details on something customers noticed.`,a:`Stripe's 'sweat the details' values the last 5%: pick an example where the polish was visible — an error message that turned a support ticket into a self-serve fix, a latency improvement users felt, an API design that made integration painless. Show the iteration: how you found the weakness, the alternatives you considered, and why you chose the one you did. Include a tradeoff you made deliberately. The subtext: Stripe believes details compound into trust, and they're hiring for that instinct.`,kp:[`visible customer-facing detail`,`iteration process`,`alternatives considered`,`deliberate tradeoff`,`measured result`,`details compound into trust`]}]},{id:`airbnb`,name:`Airbnb`,icon:`🏠`,tagline:`Travel marketplace`,hq:`San Francisco, CA`,difficulty:3,stack:[`Ruby on Rails`,`React`,`TypeScript`,`GraphQL`,`Kafka`,`MySQL`,`ML`],values:[`Champion the mission`,`Be a host`,`Embrace the adventure`,`Simplify`,`Every frame matters`],style:`Product-sense heavy: design questions that start from user needs. Mission-driven behavioral rounds. Expect 'design a feature' questions with a UX-first lens.`,sample:[{q:`Design a search and discovery feature for a travel marketplace.`,a:`Start from the user: filtering by location, dates, price, and amenity preferences, ranked by relevance (location match, reviews, price value, popularity). Architecture: search index (Elasticsearch) with filters and ranking, backed by a pipeline that indexes listings with fresh availability and pricing. The product layer: map-first vs list view, search suggestions, and saved searches. Ranking is the product: what makes a great match — and the answer should include experimentation (A/B tests) and learning from booking outcomes, not clicks.`,kp:[`user-first requirements`,`search index with filters`,`relevance ranking signals`,`availability and pricing freshness`,`map and list views`,`optimize for bookings not clicks`]},{q:`How would you handle duplicate or spam listings at scale?`,a:`Layered detection: rules at ingest (blocked patterns, velocity checks, known-bad signals), ML classification on listing content and images (duplicate detection via embeddings, spam patterns), and human review for the ambiguous tail with a trust and safety workflow. The harder, product-level work: identity verification at signup, reputation signals (reviews, host history), and making the cost of abuse high (payments friction). Track abuse metrics and iterate — spammers adapt, so detection is a treadmill, not a project.`,kp:[`rules at ingest`,`ml duplicate and spam detection`,`embeddings for similarity`,`human review for tail`,`identity and reputation signals`,`abuse as ongoing treadmill`]},{q:`Design a reviews system that users trust.`,a:`Trust is the product: both sides review (guest and host) with private feedback to reduce retaliation, reviews are locked in (can't be edited after a window, or only with transparency) to prevent pressure, and content moderation catches abusive or fake reviews. The system: review creation flow with structured categories plus free text, a moderation pipeline (automated + human), and scoring that resists gaming (recency weighting, outlier handling). Show the marketplace lens: reviews are the information that makes strangers transact, so integrity beats volume.`,kp:[`two-sided reviews`,`anti-retaliation design`,`locked reviews with transparency`,`moderation pipeline`,`gaming resistance in scoring`,`integrity over volume`]},{q:`Tell me about a time you championed the user in a product decision.`,a:`Airbnb's mission value wants the user's voice in your decision-making: a real example where you pushed for the user experience against pressure (deadline, cost, or opinion), how you made the case (research, data, prototypes), and the outcome. Show empathy as an engineering skill: how you understood the user's context and translated it into a technical or product decision. End with what the company or users gained.`,kp:[`real user-centered decision`,`made case with evidence`,`understood user context`,`pushed back constructively`,`outcome for users`,`empathy as engineering skill`]}]},{id:`uber`,name:`Uber`,icon:`🚗`,tagline:`Mobility and delivery`,hq:`San Francisco, CA`,difficulty:4,stack:[`Go`,`Java`,`Python`,`React Native`,`Kafka`,`MySQL`,`Postgres`,`Machine learning`],values:[`Customer obsession`,`We before me`,`Act like an owner`,`Always hustle`],style:`System design heavy — 'design Uber' is a classic. Real-time, geo-distributed systems with availability demands. Behavioral rounds probe ownership and hustle.`,sample:[{q:`Design the dispatch system that matches riders and drivers.`,a:`The constraints: real-time (sub-second matching), geo-distributed, and availability-critical. Architecture: drivers stream GPS to a location service (geohashed or spatial index); a dispatch service matches supply to demand optimizing a global objective (ETAs, utilization, fairness) with a batch-and-solve approach — rebalance every few seconds rather than greedily. ETA estimation needs a live map/route service. Degradation: when location data lags, match on last-known with confidence checks; when dispatch is overloaded, fall back to simpler matching rather than failing. Measure the whole thing on dispatch latency and utilization, not just match rate.`,kp:[`driver location stream`,`geohash spatial indexing`,`batch matching optimization`,`live eta and routing`,`graceful degradation on stale data`,`dispatch latency metrics`]},{q:`How would you estimate ETAs accurately across a city?`,a:`Layered estimation: real-time traffic (probe data from trips aggregated per road segment) blended with historical patterns (time of day, day of week) and static map data, with a fallback when live data is missing. The model: segment-level travel time prediction feeding a routing engine. The product layer: ETA must be honest and calibrated — a consistently wrong ETA erodes trust faster than a slower but accurate one. Monitor predicted vs actual systematically, and re-train on drift (new roads, weather, events).`,kp:[`real-time traffic probes`,`historical pattern blending`,`segment travel time model`,`honest calibrated promises`,`predicted vs actual monitoring`,`retrain on drift`]},{q:`Design a system that handles surge pricing during a rainstorm.`,a:`Surge exists to balance supply and demand: when demand outpaces supply (rain, events, rush hour), prices rise to attract more drivers and allocate scarce supply to the highest-willingness riders. The system: real-time demand/supply imbalance detection per geo region, a pricing engine that adjusts multipliers with constraints (fairness caps, transparency), and instant propagation to riders before they book. The engineering: geo aggregation of supply/demand, low-latency pricing reads, and careful experimentation — surge affects behavior of both sides, so it's validated with controlled tests, and the incentives must be communicated honestly to users.`,kp:[`supply demand imbalance detection`,`geo-region aggregation`,`pricing engine with fairness caps`,`low-latency pricing propagation`,`dual-sided behavior effects`,`honest user communication`]},{q:`Tell me about a time you went above and beyond to solve a problem.`,a:`Uber's hustle value: pick a real example where the problem was underspecified or urgent and you owned it end-to-end — took it beyond your scope, rallied the help you needed, and delivered. Show the specifics: what made it hard, the obstacles, what you did when things went wrong, and the measured result. Avoid humble-bragging about overwork; emphasize ownership and impact instead. They want to see the 'act like an owner' instinct in action.`,kp:[`real underspecified problem`,`owned it end-to-end`,`rallied resources`,`overcame obstacles`,`measured result`,`owner mindset`]}]},{id:`spotify`,name:`Spotify`,icon:`🎵`,tagline:`Music streaming`,hq:`Stockholm / New York`,difficulty:3,stack:[`Java`,`Kotlin`,`Python`,`React`,`Kafka`,`Cassandra`,`BigQuery`,`ML`],values:[`Innovation`,`Collaboration`,`Passion`,`Sincerity`],style:`Squad-based culture — expect collaboration and autonomy questions. Product metrics and experimentation feature heavily, especially for data and backend roles.`,sample:[{q:`Design a music recommendation system.`,a:`The layers: candidate generation (collaborative filtering on listening behavior, content-based on audio features/embeddings, editorial and context playlists), then ranking (a model over features: user history, freshness, genre fit, context — morning vs workout). The feedback loop is the product: skips, repeats, and saves tell you what worked. Cold start: new users get curated/contextual picks; new tracks get audio-feature-based similarity. Evaluation: offline metrics (precision@k, NDCG) plus A/B tests on engagement and retention — because the real objective is long-term engagement, not clicks.`,kp:[`collaborative and content-based candidates`,`audio features and embeddings`,`ranking with context features`,`feedback loop skips saves`,`cold start strategies`,`offline metrics plus experiments`]},{q:`How do you measure the health of a feature like Discover Weekly?`,a:`Start from the objective: does it drive long-term engagement and retention? Metrics: adoption (who uses it), engagement (listens, saves, session length), and the critical ones — retention lift for users who engage with it, and diversity of discovery (are users finding music they'd never find otherwise?). Guardrails: churn, skip rate, and diversity collapse. The analysis: cohort comparisons and A/B tests, watching not just the metric but the behavior beneath it — a feature can look great in aggregate and fail for specific segments.`,kp:[`adoption engagement retention`,`retention lift cohorts`,`discovery diversity metric`,`guardrail metrics`,`segment-level analysis`,`behavior beneath the metric`]},{q:`Design a system for streaming audio with seamless playback.`,a:`The player pipeline: audio is encoded in multiple bitrates and chunked; the player downloads ahead (buffer) while playing, switching quality based on network conditions (adaptive bitrate). Seamlessness = predicting the next song (gapless playback, crossfade) and prefetching it during the current one. Offline: full-song downloads with smart caching (cache the tracks you'll likely play next). Server side: CDN with edge caches, session management, and rights-aware delivery (what you can play depends on licensing per region). The product metrics: playback failures, rebuffer rate, and time-to-first-play.`,kp:[`adaptive bitrate chunked audio`,`prefetch and buffering`,`gapless and crossfade`,`smart offline caching`,`cdn and regional licensing`,`playback failure metrics`]},{q:`Tell me about a time you collaborated across teams to ship something.`,a:`Spotify's squad/guild model makes collaboration the interview theme: a real example where you worked across team boundaries (design, data, another squad), how you aligned goals and handled disagreement, and your specific contribution to the outcome. Show the mechanics: communication rituals, shared ownership, giving and receiving feedback. End with the result and what made the collaboration work — and be honest about what was hard.`,kp:[`real cross-team example`,`aligned goals across boundaries`,`handled disagreement`,`specific contribution`,`communication mechanics`,`honest about difficulty`]}]},{id:`cloudflare`,name:`Cloudflare`,icon:`☁️`,tagline:`CDN, security, edge`,hq:`San Francisco / London`,difficulty:4,stack:[`Go`,`Rust`,`TypeScript`,`Workers`,`ClickHouse`,`Kubernetes`],values:[`Trust`,`Curiosity`,`Scrappy`,`Transparency`],style:`Technical depth on distributed systems at the edge. Expect questions about performance, scale, and failure — they literally run a global network.`,sample:[{q:`How would you serve a request from the edge with sub-millisecond overhead?`,a:`The edge is a proxy: DNS routes the user to the nearest PoP, TLS terminates there, and the request hits a highly optimized HTTP stack. The principles: keep the hot path in memory (no disk, no network hops), minimize allocations and copies, use connection reuse and HTTP/3, and avoid per-request lock contention. Where compute is needed, run it at the edge (Workers-style) so the user never leaves the PoP. Measure everything in overhead terms: the proxy's added latency must be a small, predictable constant, verified at scale with real traffic distributions.`,kp:[`terminate at nearest PoP`,`in-memory hot path`,`minimize allocations and copies`,`connection reuse http3`,`edge compute avoids round trips`,`measure overhead as budget`]},{q:`Design a WAF (Web Application Firewall) rule engine that runs at the edge.`,a:`The constraint: evaluate rules against every request at the edge in microseconds. Architecture: compile rules (OWASP CRS + custom) into an efficient matching structure — optimized regex sets, bloom filters for cheap rejection, and early-exit evaluation — running in the request path in C/Rust/Wasm. The control plane: rule deployment must be global and fast (rule updates propagate to all PoPs in seconds) and atomic, because a bad rule is a global outage. Observability: match rates per rule, false positive detection (blocking legit traffic), and analytics so operators tune rules with data.`,kp:[`compile rules to efficient matchers`,`bloom filters and early exit`,`run in request path`,`fast atomic global rule deployment`,`false positive monitoring`,`operator analytics`]},{q:`How do you build and debug systems when every request can hit any of hundreds of edge locations?`,a:`Key insight: edge systems are many identical replicas, so determinism and reproducibility matter more than in a central service. Build for it: identical binaries/configs everywhere (config diffs are the failure mode), request tracing that works across PoPs (every edge hop carries trace context), centralized logs/metrics with local sampling, and canary rollouts that ramp percentage of PoPs. Debugging: reproduce against the exact config (record and replay), use controlled chaos (kill a PoP, see what breaks), and lean on the fleet's statistics — a bug in 1 of 300 locations is a config skew or a hardware anomaly, not a code bug.`,kp:[`identical replicas everywhere`,`cross-pop trace context`,`config skew as failure mode`,`canary pop rollouts`,`record replay reproduction`,`fleet statistics debugging`]},{q:`Tell me about a time you made a system measurably faster.`,a:`Cloudflare's 'scrappy' value wants evidence and numbers: pick a real optimization — latency, throughput, resource cost — with a before/after measured on real workloads. Show your method: profiling to find the actual bottleneck (not the guessed one), the change, the verification, and the guardrails that kept it fast (benchmarks, budgets). Include the tradeoffs you considered. A strong answer shows the discipline: measure → change → re-measure, and knowing when the optimization wasn't worth it.`,kp:[`real measured optimization`,`profiling found actual bottleneck`,`before after on real workloads`,`guardrails kept it fast`,`considered tradeoffs`,`measure change re-measure discipline`]}]},{id:`datadog`,name:`Datadog`,icon:`📈`,tagline:`Observability SaaS`,hq:`New York, NY`,difficulty:3,stack:[`Go`,`Python`,`Java`,`React`,`Kafka`,`ClickHouse`,`Elasticsearch`,`AWS`],values:[`Care about customers`,`Wear the customer's shoes`,`Be scrappy`,`Own your outcomes`],style:`Practical systems questions: ingestion pipelines, time-series storage, debugging stories. Expect 'walk me through how you debugged something hard'.`,sample:[{q:`Design a metrics ingestion pipeline that handles millions of time series.`,a:`Agents on customer hosts collect and batch metrics, sending them to ingest gateways that validate and route to storage. The storage engine is the crux: time-series data is append-heavy with high cardinality, so design for compression (delta-of-delta timestamps, XOR values — the Gorilla approach), downsampling/rollups for long retention, and sharding by series. Query path: serve recent data from hot storage, rollups for older data. The whole pipeline must absorb bursts (agents retry with backoff, gateways shed load gracefully) and never lose the customer's data silently — drop metrics loudly.`,kp:[`agent batching and retry`,`ingest gateways with backpressure`,`compression delta of delta`,`downsampling and rollups`,`shard by series`,`loud not silent drops`]},{q:`How do you build a dashboard that stays fast while querying terabytes?`,a:`The query path must never scan everything: pre-aggregate (rollups at multiple resolutions — 1s/1m/1h), push filters down to storage, and cache aggressively (same query twice → serve cache; dashboard refresh → serve cache while refreshing in background). Architect dashboards as a set of small, parallelizable queries with time bounds, and degrade gracefully: if the full-resolution query is too expensive, fall back to rollups, then to cached data — a slow dashboard is a useless dashboard. Add query cost limits and per-dashboard budgets so one team can't tax the cluster.`,kp:[`pre-aggregated rollups`,`pushdown filters`,`cache with background refresh`,`parallel small queries`,`graceful resolution fallback`,`query budgets`]},{q:`Walk me through the hardest production debugging you've done.`,a:`Datadog hires people who've felt real production pain: pick a genuinely hard incident — intermittent, distributed, or mysterious — and walk through it like a story with a method: the symptom, the hypotheses you formed and eliminated, the evidence that cracked it (logs, traces, reproductions), the root cause, and the fix. End with the systemic improvement that made it unrepeatable (monitoring, tests, architectural change). The interviewer is evaluating your debugging discipline and honesty — include a wrong turn you took.`,kp:[`hard real incident`,`systematic hypothesis elimination`,`evidence that cracked it`,`root cause and fix`,`systemic prevention`,`honest about wrong turns`]},{q:`Tell me about a time you turned customer feedback into an engineering decision.`,a:`Datadog's customer-obsession value: a real example where customer pain shaped what you built — how you heard it (support, usage data, direct conversations), how you validated it was real and general (not one loud customer), how you prioritized it, and the outcome. Show judgment in saying no to some requests, and show the loop closing: how you knew it worked (adoption, support tickets down, retention).`,kp:[`real customer pain`,`validated real and general`,`prioritized with judgment`,`shipped and measured`,`said no to some requests`,`closed the loop`]}]}];function c(e){return s.find(t=>t.id===e)||o}var l=[{q:`Tell me about a time you had a conflict with a teammate. How did you resolve it?`,a:`Use STAR: a specific situation, what you did, the result. The strongest answers show you addressed the conflict directly and respectfully — understood their perspective before arguing yours, found the shared goal underneath the disagreement, and separated the person from the problem. The outcome should include both the technical resolution and the preserved (or improved) working relationship. Interviewers are listening for emotional maturity, not for who was right.`,kp:[`specific situation`,`understood their perspective`,`shared goal framing`,`resolved constructively`,`relationship preserved`,`self-awareness`]},{q:`Describe a project you're most proud of.`,a:`Pick something with real stakes and measurable impact. Walk through: the problem and why it mattered, your specific contribution (not the team's), the obstacles and how you overcame them, and the measured result — users, revenue, performance, or velocity. Close with what you learned. Avoid picking something where you can't articulate your own role, and avoid vague impact statements — quantify.`,kp:[`specific contribution`,`why it mattered`,`obstacles overcome`,`measured impact`,`lessons learned`]},{q:`Tell me about a time you failed.`,a:`The point isn't the failure — it's your honesty and growth. Choose a real failure with real consequences (not a fake 'failure' that was actually a success), take ownership without deflecting to others or circumstances, and show what you learned and how you changed your behavior. The strongest answers include the specific mechanism that prevented the same mistake again. Interviewers distrust candidates who can't name a genuine failure.`,kp:[`honest real failure`,`took ownership`,`no deflection`,`specific learning`,`changed behavior`,`growth mindset`]},{q:`Tell me about a time you disagreed with your manager.`,a:`Show that you can challenge respectfully and commit effectively: you raised the disagreement with evidence and reasoning, listened to their counterarguments with an open mind, and either persuaded them or accepted the decision and executed fully. Avoid stories where you were right and they were wrong in a way that sounds like resentment. The evaluation is on your judgment and your ability to maintain trust through disagreement.`,kp:[`evidence-based challenge`,`respectful delivery`,`listened to counterarguments`,`accepted and committed`,`trust maintained`]},{q:`Describe a time you had to deliver under a tight deadline.`,a:`Show your prioritization under pressure: how you identified what mattered most, what you cut or negotiated in scope, how you communicated tradeoffs to stakeholders, and how you stayed calm and organized. The outcome should show you delivered the critical parts well. A strong answer includes an honest acknowledgment of what was sacrificed and whether the tradeoff was worth it.`,kp:[`prioritized ruthlessly`,`negotiated scope`,`communicated tradeoffs`,`calm under pressure`,`delivered outcome`,`honest about cost`]},{q:`Tell me about a time you mentored or helped someone grow.`,a:`Mentorship isn't just explaining things — it's diagnosis: understanding where the person actually struggles, adjusting your approach to their level, giving feedback they can act on, and building their independence rather than dependency. Describe a specific person, your approach, and the outcome — their growth, and what it did for the team. Senior-level interviews weight this heavily; it's evidence you can multiply impact.`,kp:[`diagnosed their need`,`adapted approach`,`actionable feedback`,`their growth`,`built independence`,`team benefit`]},{q:`Tell me about a time you made a decision with incomplete information.`,a:`The best answers show the decision framework: what you did to gather the fastest useful information (talk to users, run a small experiment, prototype), the assumptions you made explicit, how you decided with speed, and how you monitored and corrected course after. Interviewers at higher levels want to see comfort with ambiguity — analysis paralysis is the failure mode they're screening for.`,kp:[`gathered fastest useful info`,`explicit assumptions`,`decided with speed`,`monitored outcome`,`corrected course`,`comfort with ambiguity`]},{q:`Tell me about a time you received tough feedback.`,a:`The test is whether you can receive feedback without getting defensive. Describe the feedback, your initial reaction (honesty here earns trust), what you did with it — a concrete change — and the outcome. The strongest answers show feedback transformed into a habit, and an ongoing practice of seeking feedback rather than waiting for it. Avoid framing the feedback as unfair; own the part that was yours.`,kp:[`accepted without defensiveness`,`honest initial reaction`,`concrete change`,`measured outcome`,`seeks feedback ongoing`]},{q:`Describe a time you improved a process or workflow.`,a:`Show the full loop: how you noticed the inefficiency (often by feeling the pain yourself), how you validated the fix would help, how you implemented it and got buy-in, and the measured improvement — time saved, errors reduced, velocity up. Process improvements at higher levels scale: the same fix applied to multiple teams or codified into tooling. Include the resistance you faced, because changing process means changing people.`,kp:[`identified real inefficiency`,`validated the fix`,`got buy-in`,`measured improvement`,`scaled beyond one team`,`overcame resistance`]},{q:`Tell me about a time you handled an angry customer or stakeholder.`,a:`The skill is de-escalation and ownership: you listened fully before responding, acknowledged their frustration without being defensive, took ownership of the problem (even where it wasn't purely your fault), and either resolved it or escalated it with context. The outcome should show the relationship repaired or the situation improved. Avoid stories where the customer was simply wrong — the interesting ones have real substance.`,kp:[`listened first`,`acknowledged without defensiveness`,`took ownership`,`resolved or escalated well`,`relationship repaired`,`root cause fixed`]},{q:`Describe a time you took a calculated risk.`,a:`A calculated risk has stakes and reasoning: what was at stake, what you did to reduce the downside (experiments, fallbacks, staged rollout), the decision itself, and the outcome. The best answers are honest about the tension — if it had no real downside, it wasn't a risk. Higher-level interviews want to see risk appetite calibrated to impact: big risks on reversible decisions, caution on irreversible ones.`,kp:[`real stakes`,`reduced the downside`,`explicit reasoning`,`outcome`,`reversible vs irreversible`,`lesson learned`]},{q:`Tell me about a time you worked on a cross-functional team.`,a:`Show you can operate where goals, vocabulary, and incentives differ: the roles involved (design, product, data, other engineering teams), how you aligned on a shared goal, how you communicated across the gap, your specific contribution, and the result. The strongest answers show you actively bridging — translating technical constraints into product terms and vice versa. Conflict or misalignment in the story is a feature, not a flaw, if you handled it well.`,kp:[`diverse roles involved`,`aligned shared goals`,`bridged communication gap`,`specific contribution`,`handled misalignment`,`measured result`]}],u={mid:[{q:`Design a URL shortener.`,a:`Requirements and scale first: ~100M URLs, read-heavy (100:1). Core: generate a short unique key (base62 encoding of a counter or hash with collision handling), store the mapping in a database with the key as primary key, and serve redirects (301 for permanent, 302 for analytics). Reads dominate, so cache hot mappings and put a CDN in front. Add optional analytics (click counts, referrers) via an event pipeline. Edge cases: custom aliases, key reuse, and expiry.`,kp:[`requirements and scale estimate`,`base62 key generation`,`collision handling`,`301 302 redirect semantics`,`cache hot mappings`,`analytics pipeline`]},{q:`Design a chat application.`,a:`Transport: WebSockets for real-time delivery and presence, with a fallback to polling/SSE. Storage: messages in a sharded database, paginated by conversation; each conversation gets a monotonically increasing sequence for sync. States: sent → delivered → read, tracked per message. Offline: client queue with resync on reconnect using the sequence. Group chats fan out; large groups use a pull model. Push notifications cover the app-not-open case. Scale: shard by conversation or user, and make message IDs idempotent for retries.`,kp:[`websocket real-time transport`,`message storage and pagination`,`sequence-based sync`,`delivery statuses`,`offline queue and resync`,`sharding strategy`]},{q:`Design a news feed.`,a:`The core tradeoff is fan-out: on write, push the post to followers' caches at write time (fast reads, expensive for celebrities); on read, merge posts from followed users at request time (simple, slower). Large systems use a hybrid — push for most users, pull for high-follower accounts. Ranking combines recency, affinity, and engagement. The feed is a per-user cache with cursor pagination, backed by a cache tier (Redis) over the source data. Consistency is eventual: a story arriving a minute late is acceptable.`,kp:[`fan-out on write vs read`,`hybrid for high-follower accounts`,`ranking signals`,`per-user cache`,`cursor pagination`,`eventual consistency`]},{q:`Design a rate limiter.`,a:`Algorithm: token bucket (simple, allows bursts) or sliding window (smoother). Track counters per key (user/IP/API key) in a fast store like Redis with TTLs, using atomic operations for distributed correctness. Enforce at the gateway or middleware; on violation return 429 with Retry-After. The limiter itself must scale horizontally and never be a bottleneck — degrade gracefully if the counter store is down (allow, don't block, with a circuit breaker). Monitor usage to tune limits and detect abuse.`,kp:[`token bucket or sliding window`,`counters with ttl`,`atomic distributed ops`,`429 with retry-after`,`graceful degradation`,`abuse monitoring`]}],senior:[{q:`Design a social media platform like Twitter/X.`,a:`Core components: a post service (content storage, sharded by post ID or user), a timeline service with fan-out (push to followers' timelines at write time, pull for high-follower accounts), and a search/trends service over the post stream. Caching dominates: hot users' timelines are precomputed and cached; the top posts of the day get dedicated cache layers. Consistency: eventual — a timeline slightly behind is fine; the failure mode to design for is the celebrity posting (write storm) and the viral event (read storm).`,kp:[`post storage sharding`,`timeline fan-out`,`celebrity pull model`,`cache hierarchy`,`write storm handling`,`eventual consistency`]},{q:`Design a video streaming platform like Netflix.`,a:`Two planes: the control plane (catalog, recommendations, auth) and the data plane (the actual video bytes). Data plane: content is transcoded into multiple qualities and chunked, distributed to a CDN with caches near users; the player uses adaptive bitrate to pick quality by bandwidth. The catalog/metadata service is a classic read-heavy service with caching. Recommendations are a separate offline pipeline (see recommendation design). DRM and licensing gate what can play where. The economics — storage and bandwidth per title — are first-class design constraints.`,kp:[`control plane data plane separation`,`transcoding quality ladder`,`cdn distribution`,`adaptive bitrate playback`,`catalog service caching`,`drm and licensing`]},{q:`Design a ride-hailing system like Uber.`,a:`The heart is dispatch: drivers stream location to a location service (spatial index, geohash), and a dispatch service matches supply to demand in batches, optimizing a global objective (ETA, utilization, fairness) rather than greedily. ETA estimation needs a live routing service. Trip state machine: request → match → pickup → ride → payment → rating, each an event. Real-time components (location, dispatch) are the hard availability problem; trip history and payments can be eventually consistent. Degrade gracefully: stale locations, overloaded dispatch, and low supply all have fallbacks.`,kp:[`driver location stream`,`spatial index geohash`,`batch matching optimization`,`trip state machine`,`live eta routing`,`graceful degradation`]},{q:`Design a distributed key-value store like Dynamo.`,a:`Consistent hashing partitions data across nodes with virtual nodes for even distribution; each key is replicated to N successor nodes for availability. Reads/writes use quorum (R + W > N) to balance consistency and latency. Conflicts (concurrent writes) are resolved with vector clocks — keep both versions and let the application resolve, or last-write-wins. Hinted handoff keeps availability when a node is down, and Merkle trees detect divergence for anti-entropy. This is the AP-end of the spectrum: availability over strong consistency.`,kp:[`consistent hashing with virtual nodes`,`replication factor`,`quorum reads and writes`,`vector clocks for conflicts`,`hinted handoff`,`merkle tree anti-entropy`]}],staff:[{q:`Design a payment system that must never lose money.`,a:`The invariants: every operation is idempotent (unique constraint on idempotency keys), and money movement is recorded in an append-only ledger with double-entry accounting — every debit has a credit, so the books always balance. External providers are reconciled against the ledger asynchronously with mismatch alerts. Compensating transactions, not mutation: a failed capture after a hold releases, never deletes. Add an immutable audit trail, isolate the money path from the main CRUD app, and make the ledger the source of truth.`,kp:[`idempotency unique constraints`,`append-only double-entry ledger`,`reconciliation with providers`,`compensating transactions`,`immutable audit trail`,`ledger as source of truth`]},{q:`Design a search engine.`,a:`Three systems: crawling (discover and fetch pages, politeness, dedupe), indexing (parse, tokenize, build the inverted index, plus auxiliary indexes for freshness and metadata), and serving (query parsing, ranking, and retrieval in milliseconds). Ranking is the product: relevance (BM25, embeddings), authority (PageRank-style), freshness, and personalization, trained on click feedback. Scale: the index is sharded by document, the query is broadcast and merged; hot queries are cached. Freshness adds the crawl-reindex loop.`,kp:[`crawler with politeness`,`inverted index`,`ranking relevance authority freshness`,`sharded index and query merge`,`click feedback loop`,`crawl reindex freshness`]},{q:`Design a globally distributed database with strong consistency where it matters.`,a:`The design tension: strong consistency across regions costs latency. The answer is tiered: a consensus-based replicated core (Paxos/Raft) for the data that must be strongly consistent, with transaction routing that pins related operations to one region, and replication-based eventual consistency for the rest. Read-your-writes for the current session is the pragmatic middle ground. Failover: automatic leader election, with periodic DR drills validating RPO/RTO. The honest answer includes what you refuse to make strongly consistent because the latency cost isn't worth it.`,kp:[`consensus replication paxos raft`,`tiered consistency`,`transaction routing to region`,`read-your-writes sessions`,`automatic failover and drills`,`refuse consistency where it costs`]},{q:`Design a recommendation infrastructure at scale.`,a:`Two stages at serving time: candidate generation (broad recall — item-item similarity, user embeddings, contextual rules) and ranking (a model scoring candidates on features from a feature store). The platform pieces: a feature store for consistent training/serving, an offline pipeline that trains on logs, an online pipeline that serves and logs new interactions, and an experimentation platform to A/B test. The loop is the product: recommendations learn from feedback, so the pipeline's freshness, latency, and logging quality matter more than any single model.`,kp:[`candidate generation and ranking`,`feature store consistency`,`offline training online serving`,`feedback loop logging`,`experimentation platform`,`freshness latency quality`]}],principal:[{q:`Design an event streaming platform like Kafka from first principles.`,a:`The core abstraction is the log: an ordered, immutable, append-only sequence of records, partitioned for parallelism with per-partition ordering. Durability comes from replication (leader + ISR followers) with acks configurable from fire-and-forget to all. Consumers coordinate via consumer groups — each partition assigned to one consumer for ordering. The hard parts: retention and compaction, exactly-once semantics (transactional producers and consumer offsets), scaling (partition counts, broker limits), and operational concerns (rebalancing storms, disk layout, zookeeper/KRaft).`,kp:[`log as core abstraction`,`partitions with per-partition ordering`,`replication with ISR`,`consumer groups`,`retention and compaction`,`rebalancing and operations`]},{q:`Design a multi-tenant SaaS platform architecture.`,a:`Separate control plane from data plane: the control plane handles onboarding, provisioning, billing, and configuration; the data plane runs tenant workloads. Isolation is a spectrum — shared infrastructure with strong logical isolation (multi-tenant compute, per-tenant namespaces) up to dedicated clusters for enterprises that demand it, priced accordingly. Metering and billing are their own pipeline (usage events → aggregation → invoices). The operational demands: onboarding automation, per-tenant quotas and noisy-neighbor control, and per-region compliance.`,kp:[`control plane data plane split`,`isolation spectrum and pricing`,`metering and billing pipeline`,`onboarding automation`,`per-tenant quotas`,`regional compliance`]},{q:`Design a platform serving 1B requests/day with 99.99% availability.`,a:`Start with the SLO, because it defines everything: 99.99% is ~52 minutes of downtime a year, so design for redundancy at every layer — multiple zones, active-active regions where it pays, no single points of failure, and graceful degradation (feature shutdowns, cache fallbacks) that keeps the core alive when the periphery fails. Capacity planning with headroom, load testing to find limits, and automation for rollouts and rollbacks. The culture: error budgets, blameless postmortems, and game days, because availability is a property of the operating system, not just the code.`,kp:[`slo defines design`,`multi-zone redundancy`,`graceful degradation`,`capacity and load testing`,`automated rollback`,`error budget culture`]},{q:`Design the architecture for an AI assistant platform.`,a:`Layers: a gateway that authenticates, routes, and guards every prompt; model serving (with a pool of models tiered by task and cost); retrieval-augmented generation with a vector store of the user's knowledge; and a context/prompt management layer that assembles the right context cheaply (prompt caching, compression). The hard engineering: cost and latency control (caching, model tiering, rate limits, streaming), safety and guardrails (prompt injection defenses, content filters, audit logs), and observability (cost per request, quality sampling, feedback collection).`,kp:[`gateway auth routing guards`,`model tiering by cost`,`retrieval augmented generation`,`prompt caching and compression`,`prompt injection defenses`,`cost observability per request`]}]},d=[{q:`How would you build the engineering org as the company scales from 20 to 200 engineers?`,a:`Sequence matters more than structure. At 20, keep teams flat and delivery-obsessed; hire senior leaders early (staff/principal engineers and tech leads) because they set the patterns everyone copies. Around 50+, organize into product-aligned teams with clear ownership, and add only the process that removes real pain — retros, on-call, design review — never process as decoration. Invest in the leadership pipeline (tech lead training) and a hiring engine that scales with you. The failure mode to avoid: over-hierarchizing early, or under-structuring late.`,kp:[`flat and delivery-focused early`,`hire senior leaders first`,`product-aligned teams`,`process for pain not decoration`,`leadership pipeline`,`avoid premature hierarchy`]},{q:`How do you set the technical vision and get the org behind it?`,a:`A vision no one can explain is a hallucination. Start by aligning with the business: what must the technology make possible in 2-3 years? Write it as a short, concrete document — the bets, the tradeoffs, what we will NOT do — and socialize it relentlessly: town halls, one-on-ones, and early wins that prove the direction works. Make decision-making inclusive (senior voices disagreeing early), then decisive. Review the vision quarterly against reality; a vision that can't change is a dogma.`,kp:[`aligned to business goals`,`short concrete document`,`explicit tradeoffs and non-goals`,`socialize relentlessly`,`early proof wins`,`review and adapt quarterly`]},{q:`How do you think about build vs buy vs partner for core infrastructure?`,a:`The lens is core vs context: if a capability is your competitive advantage, build it; if it's table stakes, buy or use managed services. Then the real math: total cost of ownership including operations and on-call (a 'free' open-source database you run yourself is rarely free), lock-in and exit costs, and your team's capacity to operate it. Timing matters: buy early to move fast, build once you understand the problem deeply — building what you don't understand is how you get a worse version of a product someone else sells.`,kp:[`core vs context competency`,`tco including operations`,`lock-in and exit costs`,`team capacity to operate`,`buy early build once understood`,`reversible decisions`]},{q:`How do you manage the engineering budget (headcount, cloud, tools)?`,a:`Budget is strategy with numbers: start from business priorities, not last year plus 10%. Headcount: model productivity per engineer honestly (team size has diminishing returns — 10 great engineers beat 30 mediocre ones). Cloud cost: make it visible per team (tagging, showback) and attack structural waste — rightsizing, commitments, idle resources. Tools: audit what's actually used and kill the SaaS graveyard. The discipline: a monthly review of spend vs value, with the same rigor as revenue review. Frugality is a feature when it's about focus, not penny-pinching.`,kp:[`budget follows priorities`,`diminishing returns on headcount`,`cloud cost visibility per team`,`tool spend audit`,`monthly spend value review`,`frugality as focus`]},{q:`How do you ensure security and compliance without slowing delivery?`,a:`The answer is risk-tiered controls and automation: secure defaults in frameworks and templates (paved roads), automated scanning in CI (SAST, dependencies, secrets) so security is a side effect of normal work, and human review reserved for genuinely high-risk changes. Compliance is automated where possible (evidence collection, policy-as-code) and mapped to what customers actually require — don't build for regulations you don't face. Security champions per team keep it human. The culture piece: security is everyone's job, and the security team measures friction and unblocks rather than blocks.`,kp:[`risk-tiered controls`,`automated scanning in CI`,`secure defaults paved roads`,`compliance automated and scoped`,`security champions`,`measure and reduce friction`]},{q:`How do you handle a major production incident as CTO?`,a:`Your job in the first hour is presence, not diagnosis: confirm the facts, set the communication cadence (internal, customers, execs), and make sure the right people are working without interference. Let the engineers work — your role is removing obstacles, not hovering. After recovery, drive the postmortem culture: blameless analysis, action items with owners, and a public 'what we learned' that builds trust. The CTO-level question is systemic: what made this possible, and what structural change prevents the class of incident, not just this one?`,kp:[`presence and communication first`,`let experts work`,`removing obstacles`,`blameless postmortem`,`prevent the class not the instance`,`customer trust rebuilt`]},{q:`How do you hire and retain senior and staff engineers?`,a:`Hiring: a compelling mission and real technical problems, a fast and respectful process, and senior people who interview well (candidates hire the team, not the logo). The bar: structured interviews calibrated across the org, and a hiring bar that's about judgment, not trivia. Retention is the harder half: meaningful work, a visible career path (what does 'staff' mean here?), technical challenges that grow, and a culture of respect — people leave managers and boredom more than compensation. Track retention by tenure and by reason, and treat attrition as a product problem.`,kp:[`compelling mission and problems`,`fast respectful process`,`structured calibrated bar`,`visible career paths`,`challenging meaningful work`,`retention as product problem`]},{q:`How do you measure engineering productivity and health?`,a:`Start from outcomes, not vanity metrics: DORA (deploy frequency, lead time, change failure rate, MTTR) measures delivery, and developer satisfaction (surveys, eNPS) measures the experience. The traps: gaming metrics (cycle time that punishes hard work), and mistaking activity (PRs, hours) for productivity. Use metrics for diagnosis, not judgment — a slow team is usually blocked (dependencies, architecture, process) rather than lazy. And measure what the business feels: does engineering speed translate to business outcomes? That's the metric that matters to the CEO.`,kp:[`DORA delivery metrics`,`developer satisfaction surveys`,`diagnosis not judgment`,`outcomes over activity`,`find blockers not blame`,`business outcome correlation`]},{q:`How do you decide when to introduce a new technology?`,a:`Problem first, technology second — a new tool without a named problem is a hobby. Run a spike or POC against real workloads (synthetic benchmarks lie), check operational readiness (can we run, monitor, and troubleshoot this at scale, and who owns it?), model the cost honestly including migration, and have an exit strategy. The org-wide rule: a small number of blessed technologies, with a lightweight exception process — not because one stack is objectively best, but because fragmentation is a tax everyone pays. And respect the adoption curve: the first team to adopt pays the integration cost; reward them.`,kp:[`problem first not technology`,`POC with real workloads`,`operational readiness and ownership`,`honest cost and exit strategy`,`blessed stacks with exceptions`,`reward early adopters`]},{q:`How do you work with the CEO and board on technical topics?`,a:`Translation is the job: the CEO cares about outcomes, risk, and cost — not architecture. Report in business terms: what technology enables or blocks, what risks exist (and their probabilities and mitigations), and what investments cost and return. Be honest about timelines (underpromise), surface bad news early with options, and educate patiently — a board that understands your technical bets is an asset in a crisis. The cadence: regular, structured updates (monthly for the CEO, quarterly for the board) with metrics, not vibes.`,kp:[`translate tech to business outcomes`,`honest timelines and bad news early`,`risk framed with probabilities`,`regular structured cadence`,`educate the board`,`metrics not vibes`]},{q:`How would you approach the technical due diligence of an acquisition?`,a:`The goal is knowing what you're buying and what it costs to integrate. Assess: architecture health (monolith vs modular, tech debt that blocks velocity), the security and compliance posture (a breach in your acquisition is your breach), key personnel (are the people who understand the system staying?), and integration cost (identity, data, CI/CD, culture). Score against a rubric and be honest about the deal-breakers. The post-acquisition plan matters as much as the assessment: what to keep, what to migrate, and what to decommission — most acquirers overpay for code they rewrite and underpay for the team.`,kp:[`architecture and tech debt`,`security and compliance posture`,`key personnel retention`,`integration cost identity data`,`deal-breaker honesty`,`post-acquisition plan`]},{q:`What does a great engineering culture look like, and how do you build it?`,a:`Culture is the system of beliefs that survive when you're not in the room: psychological safety (people can raise problems and be wrong without punishment), blameless learning from failures, high standards enforced kindly, and ownership with trust. You build it by modeling it — the CTO's behavior is the culture — and by the decisions you make: how you react to a postmortem, whether you reward surfacing problems, who you promote. Codify the values, hire and fire for them, and revisit them as the org grows. Culture is built in small moments, not offsites.`,kp:[`psychological safety`,`blameless learning`,`high standards with kindness`,`ownership and trust`,`modeling from leadership`,`promote and hire for values`]}],f=[{q:`How do you evaluate a new market opportunity?`,a:`The framework: market size and growth (is the pool big and growing?), the pain (how acute, how often, who feels it?), competition (is the wedge defensible — technology, network effects, brand?), unit economics (can the business model work at scale?), and timing (is the market ready — too early kills as surely as too late). Then the founder's question: why us, why now? The honest answer admits you can't validate a market from a spreadsheet — the evaluation ends with talking to real customers, not slides.`,kp:[`market size and growth`,`acute customer pain`,`defensible wedge`,`unit economics`,`timing readiness`,`validate with customers`]},{q:`How do you think about pricing strategy?`,a:`Price is a product decision: it signals positioning, selects customers, and funds everything else. Start from value delivered (what does the customer's problem cost them?), not cost-plus — price to value, then verify with willingness-to-pay research and experiments. Anchor against the alternative (the status quo, the competitor), and think about the architecture: per-seat vs usage vs value-based tiers, with a free tier where it feeds adoption. The discipline: pricing is changeable, so instrument it (conversion, churn by plan) and iterate; leaving money on the table is a strategy too — for early adoption.`,kp:[`value-based not cost-plus`,`willingness to pay research`,`positioning and customer selection`,`tier architecture`,`experiment and iterate`,`pricing as product signal`]},{q:`How do you raise capital and manage investors?`,a:`Raising is a story plus evidence: the market, the insight, the traction, and the team — told with a clear ask. Choose investors for the long game (value beyond money: network, hiring help, honesty), not just valuation; term sheets have teeth, so understand the terms (liquidation preference, board seats, pro-rata). Post-raise, treat investors as stakeholders to manage deliberately: honest monthly updates, early disclosure of problems, and a board that adds value. Runway discipline is the non-negotiable: know your burn, raise before you need to, and never let fundraising become the strategy.`,kp:[`story plus traction evidence`,`investors as long-term partners`,`understand term sheet terms`,`honest regular communication`,`board management`,`runway discipline`]},{q:`How do you set company strategy for the next 12 months?`,a:`Strategy is choices: what to do AND what to explicitly not do. Start from the vision (3-5 years), then pick the few bets that move the needle this year — for a startup, usually one thing matters most (product-market fit, or the growth engine). Translate bets into OKRs with owners and metrics, allocate resources accordingly (including killing things), and set a review cadence (monthly at minimum) where strategy meets reality. The discipline is focus: a strategy that tries to do everything is a wish list.`,kp:[`choices including non-goals`,`vision to annual bets`,`few high-leverage priorities`,`OKRs with owners and metrics`,`resource allocation follows bets`,`monthly review against reality`]},{q:`How do you hire your first executives?`,a:`Your first execs are co-founders in all but name: they define the company's DNA in their function. Look for complementary strengths (you're product-obsessed? hire the operator), values alignment you've verified in person, a track record at the right stage (a 10,000-person company exec often fails at 50), and reference checks that go beyond the list — call people they've worked for and people they've managed. Set clear mandates and success criteria for the first 90 days, integrate them deliberately (they're joining your culture, not just your company), and move fast if it's wrong — a bad exec hire is a two-year tax.`,kp:[`complementary strengths`,`values alignment verified`,`right stage experience`,`deep reference checks`,`90-day mandate`,`move fast on misfires`]},{q:`How do you build a company culture from day one?`,a:`Culture forms whether you design it or not — the job is making it deliberate. Define a small number of real values (3-5, not a poster on the wall): what you reward, what you tolerate, what you fire for. Then live them visibly: the CEO's behavior is the strongest signal; hiring and firing for values is the second. Build the rituals early (all-hands, retros, decision cadence) because they compound. And be honest that culture is tested in bad times — how you handle a layoff or a scandal defines it more than any offsite.`,kp:[`few real values`,`values in hiring and firing`,`leadership models culture`,`rituals that compound`,`tested in bad times`,`deliberate not accidental`]},{q:`How do you make decisions when data is incomplete?`,a:`The framework: separate reversible from irreversible decisions. For reversible ones, decide fast with the best available data and correct as you learn — speed is a feature, and you get feedback quickly. For irreversible ones, slow down: get the most decision-relevant information fast (customers, small experiments), name your assumptions explicitly, and put tripwires in place to detect when you're wrong. Own the decision either way. The failure mode to avoid is decision paralysis dressed as rigor — most companies die of hesitation, not wrong turns.`,kp:[`reversible vs irreversible`,`speed on reversible`,`fast relevant information`,`explicit assumptions`,`tripwires to detect error`,`own the outcome`]},{q:`How do you handle a crisis (product, PR, or financial)?`,a:`The playbook: stabilize first (protect customers and operations), communicate early and honestly — silence is a message and it's usually the wrong one — and take ownership even where fault is shared. Put the best people on the fix with a clear owner and cadence, and protect the team's morale through it. Then the CEO-level work: learn systemically (what allowed this?), communicate the changes publicly, and rebuild trust deliberately — trust earned in crises outlasts the crisis itself. Never lie; a crisis found in a lie is a different, worse company.`,kp:[`stabilize and protect customers`,`communicate early and honestly`,`take ownership`,`clear owner and cadence`,`systemic learning`,`rebuild trust deliberately`]},{q:`How do you think about product-market fit and when to pivot?`,a:`Product-market fit is measurable: retention (do users come back and stay?), willingness to pay, and the growth signal (word-of-mouth, organic). Define your fit metrics explicitly — for most products it's retention curves, not acquisition. When the data says no fit, pivot deliberately: keep what works (the insight, the team, the assets), change the what or the who, and re-test with a fast experiment. The failure modes: pivoting on vibes before the data is clear, and refusing to pivot because of sunk cost. Bias toward action either way — fit is found by iterating, not deliberating.`,kp:[`retention defines fit`,`willingness to pay`,`organic growth signal`,`deliberate pivot keeps insights`,`avoid sunk cost`,`iterate fast`]},{q:`How do you manage cash flow and burn?`,a:`Cash is oxygen: you manage it weekly, not quarterly. Know your runway (cash / net burn) at all times, model scenarios (base, bad, terrible) and pre-decide the triggers for action at each level. Attack burn structurally, not with heroics: the biggest lines (headcount, infra) get the scrutiny. Revenue-side: shorten the cash conversion cycle (collect faster, bill better). Raise before you need to — the worst fundraising happens from desperation. And the discipline that matters: spending decisions get the same rigor as revenue decisions, which is rare and which is why most companies die of small leaks, not one big event.`,kp:[`runway tracked weekly`,`scenario planning with triggers`,`structural cost attack`,`shorten cash conversion cycle`,`raise before needed`,`spend rigor equals revenue rigor`]},{q:`How do you communicate with employees during uncertain times?`,a:`Uncertainty is managed with honesty and cadence: say what you know, what you don't, and when you'll know more — employees fill silence with the worst-case story, so the cost of opacity is fear. Communicate in person or live where possible, repeat the message (people hear things once), and answer the hard questions directly, including the ones you'd rather avoid. Give the team agency: what they can control, and how they contribute. And remember the emotional dimension — empathy isn't weakness, and the team's trust in you is the company's real balance sheet during a storm.`,kp:[`honesty about unknowns`,`cadence beats silence`,`answer hard questions`,`repeat and clarify`,`give agency`,`empathy builds trust`]},{q:`What metrics would you track for a SaaS business?`,a:`The scoreboard: ARR and its growth rate (headline), net revenue retention (the best single health metric — do customers expand?), gross margin (is the business model structurally sound?), CAC and the payback period, and logo churn with reasons. Behind the headline numbers: cohort retention curves (the future in miniature), usage and engagement (leading indicator of churn), and unit economics per segment. The discipline: a small dashboard of the metrics that drive decisions, reviewed weekly with the exec team — and a willingness to change what's on it as the company's stage changes.`,kp:[`arr and growth rate`,`net revenue retention`,`gross margin`,`cac payback and churn`,`cohort retention curves`,`usage as leading indicator`]}];function p(e){let t=e.slice();for(let e=t.length-1;e>0;e--){let n=Math.floor(Math.random()*(e+1));[t[e],t[n]]=[t[n],t[e]]}return t}function m(e,t){return t<=0?[]:p(e).slice(0,Math.min(t,e.length))}var h=new Set(`a an the and or but if of to in on at for with from by as is are was were be been being it its this that these those do does did done has have had i you he she we they them their your my our his her not no can could will would should may might must shall than then so such there here what which who whom when where why how all any both each few more most other some only own same very just about into over under up out off above below again once also too`.split(` `));function g(e){return String(e||``).toLowerCase().replace(/[^a-z0-9\s-]/g,` `).split(/[\s-]+/).filter(e=>e.length>1&&!h.has(e))}var _=e=>g(e).filter(e=>e.length>2),v=e=>e.length>6&&e.endsWith(`ing`)?e.slice(0,-3):e.length>5&&e.endsWith(`ed`)?e.slice(0,-2):e.length>4&&e.endsWith(`ies`)?e.slice(0,-3)+`y`:e.length>3&&e.endsWith(`s`)